// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t) public {
        t = bound(t, 1, type(uint256).max); // genesis at 0, so t >= 1
        vm.warp(t);
        address actor = address(0xBEEF);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        try new Caller().deposit{value: 10 ether}(payable(address(c))) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.pastBlockTime() == t, "first deposit at t>=1 succeeds and records t");
    }
}

contract Caller {
    function deposit(address payable target) external payable {
        target.call{value: msg.value}("");
    }
}
